B.Q6=new A.a(B.b,"Se voc\xea est\xe1 come\xe7ando agora\u2026")
B.a21=new A.a(B.c,"n\xe3o espere uma m\xe1gica.")
B.Nj=new A.a(B.c,"Espere um relacionamento.")
B.Xb=new A.a(B.b,"Porque o maior milagre n\xe3o \xe9 Deus resolver sua vida r\xe1pido.")
B.Gj=new A.a(B.c,"\xc9 Ele te transformar em algu\xe9m que sabe viver com Ele.")
B.Sg=new A.a(B.j,"Filho N\xe3o Desiste no Meio do Processo")
B.Vp=new A.a(B.b,"Se tem uma coisa que mudou em mim foi isso:")
